import pennylane as qml
import numpy as np

def second_renyi_entropy(rho):
    return -np.log2(np.trace(np.dot(rho, rho)))

def compute_entropy(circuit):
    dev = qml.device("default.qubit", wires=3)

    @qml.qnode(dev)
    def circuit_qnode():
        circuit()
        return qml.density_matrix([1])

    rho = circuit_qnode()
    return second_renyi_entropy(rho)

def circuit1():
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])

def circuit2():
    qml.Hadamard(wires=0)
    qml.CRY(np.pi/4, wires=[0, 1])
    qml.Toffoli(wires=[0, 1, 2])
    qml.CNOT(wires=[1, 2])
    qml.PauliX(wires=0)

entropy1 = compute_entropy(circuit1)
entropy2 = compute_entropy(circuit2)

print("Second Rényi entropy for circuit 1:", entropy1)
print("Second Rényi entropy for circuit 2:", entropy2)

