import pennylane as qml
import numpy as np

def compare_circuits(theta1, phi1, theta2, phi2):
    dev = qml.device("default.qubit", wires=1)

    @qml.qnode(dev)
    def circuit1():
        qml.RX(theta1, wires=0)
        qml.RY(phi1, wires=0)
        return qml.expval(qml.PauliX(0))

    @qml.qnode(dev)
    def circuit2():
        qml.RX(theta2, wires=0)
        qml.RY(phi2, wires=0)
        return qml.expval(qml.PauliX(0))

    expval1 = circuit1()
    expval2 = circuit2()

    return np.abs(expval1 - expval2)

# Example usage
