print(difference)

import pennylane as qml
import json

def run(json_params, shift):
    params = json.loads(json_params)
    theta = params['theta']

    dev = qml.device("default.qubit", wires=1)

    @qml.qnode(dev)
    def circuit(param):
        qml.RY(param, wires=0)
        return qml.expval(qml.PauliZ(0))

    def parameter_shift_term(param, shift):
        forward = circuit(param + shift)
        backward = circuit(param - shift)
        return (forward - backward) / (2 * qml.math.sin(shift))

    gradient = parameter_shift_term(theta, shift)
    return json.dumps(gradient)

