import pennylane as qml
import numpy as np

def image_to_quantum(image):
    num_qubits = len(image)
    dev = qml.device("default.qubit", wires=num_qubits)

    @qml.qnode(dev)
    def circuit(image):
        for i in range(num_qubits):
            qml.RY(image[i], wires=i)
        return [qml.expval(qml.PauliZ(i)) for i in range(num_qubits)]

    return circuit(image)

# Example usage
image = np.array([0.1, 0.2, 0.3])  # Example image data
expectation_values = image_to_quantum(image)
print(expectation_values)

