import torch
import torch.nn as nn
import pennylane as qml
from pennylane import numpy as np

class QuantumConvLayer(nn.Module):
    def __init__(self, input_filters, output_filters, kernel_size, stride):
        super(QuantumConvLayer, self).__init__()
        self.input_filters = input_filters
        self.output_filters = output_filters
        self.kernel_size = kernel_size
        self.stride = stride
        self.weights = nn.Parameter(0.01 * torch.randn(output_filters, input_filters, kernel_size))

    def forward(self, x):
        batch_size, _, width = x.shape
        output_width = (width - self.kernel_size) // self.stride + 1
        outputs = torch.zeros((batch_size, self.output_filters, output_width))

        for b in range(batch_size):
            for out_f in range(self.output_filters):
                for i in range(output_width):
                    start = i * self.stride
                    end = start + self.kernel_size
                    input_segment = x[b, :, start:end]
                    outputs[b, out_f, i] = self.quantum_conv(input_segment, self.weights[out_f])

        return outputs

    def quantum_conv(self, input_segment, weights):
        dev = qml.device("default.qubit", wires=self.kernel_size)

        @qml.qnode(dev)
        def circuit(inputs, weights):
            for i in range(self.kernel_size):
                qml.RY(inputs[i], wires=i)
            for i in range(self.kernel_size):
                qml.RY(weights[i], wires=i)
            return qml.expval(qml.PauliZ(0))

        inputs = np.array(input_segment.detach().numpy(), requires_grad=False)
        weights = np.array(weights.detach().numpy(), requires_grad=True)
        return circuit(inputs, weights)

# Example usage
input_data = torch.rand(1, 1, 5)  # Batch size of 1, 1 input filter, width of 5
quantum_conv_layer = QuantumConvLayer(input_filters=1, output_filters=1, kernel_size=3, stride=1)
output = quantum_conv_layer(input_data)
print(output)

