def estimate(workflow):
    if isinstance(workflow, qml.QNode):
        return workflow.qtape.get_resources()
    elif isinstance(workflow, qml.ResourceOperator):
        return workflow.get_resources()
    elif callable(workflow):
        def wrapper(*args, **kwargs):
            result = workflow(*args, **kwargs)
            if isinstance(result, qml.QNode):
                return result.qtape.get_resources()
            elif isinstance(result, qml.ResourceOperator):
                return result.get_resources()
            else:
                raise ValueError("Callable did not return a QNode or ResourceOperator.")
        return wrapper
    else:
        raise TypeError("Unsupported workflow type.")

