def custom_vjp(tapes, dys):
    new_tapes = []
    for tape in tapes:
        for op in tape.operations:
            if isinstance(op, qml.RX) or isinstance(op, qml.RY):
                shift = np.pi / 2
                for s in [shift, -shift]:
                    new_tape = tape.copy()
                    new_tape.set_parameters([p + s if i == op.idx else p for i, p in enumerate(tape.get_parameters())])
                    new_tapes.append(new_tape)
    return new_tapes, lambda results: [0.5 * (r1 - r2) for r1, r2 in zip(results[::2], results[1::2])]

