import pennylane as qml
from pennylane import numpy as np

def validate_measurements(tape):
    for m in tape.measurements:
        if m.return_type in {qml.measurements.Expectation, qml.measurements.Variance}:
            if len(m.wires) > 1:
                raise ValueError("Expectation and Variance measurements must be on a single wire.")
        elif m.return_type == qml.measurements.Probability:
            if len(m.wires) != tape.num_wires:
                raise ValueError("Probability measurements must be on all wires.")
        elif m.return_type == qml.measurements.State:
            if len(m.wires) != tape.num_wires:
