import pennylane as qml
from pennylane import numpy as np

def decompose_operations(tape, supported_ops):
    decomposed_tapes = []

    for op in tape.operations:
        if op.name in supported_ops:
            decomposed_tapes.append(qml.tape.QuantumTape([op], tape.measurements))
        else:
            try:
                decomposition = op.decomposition(*op.data, wires=op.wires)
                decomposed_tapes.append(qml.tape.QuantumTape(decomposition, tape.measurements))
            except NotImplementedError:
                raise ValueError(f"Operation {op.name} cannot be decomposed")

    def processing_fn(results):
        return results

    return decomposed_tapes, processing_fn

