import pennylane as qml
from pennylane import numpy as np

def batch_jvp(tapes, tangents, reduction='append'):
    dev = qml.device('default.qubit', wires=2)

    @qml.qnode(dev)
    def circuit(params):
        qml.RX(params[0], wires=0)
        qml.RY(params[1], wires=1)
        return qml.expval(qml.PauliZ(0)), qml.expval(qml.PauliZ(1))

    jvps = []
    for tape, tangent in zip(tapes, tangents):
        jacobian = qml.jacobian(circuit)(tape)
        jvp = np.dot(jacobian, tangent)

        if reduction == 'append':
            jvps.append(jvp)
        elif reduction == 'sum':
            jvps.append(np.sum(jvp))
        elif reduction == 'mean':
            jvps.append(np.mean(jvp))
        else:
            raise ValueError("Invalid reduction method")

    return jvps

# Example usage
tapes = [np.array([0.1, 0.2]), np.array([0.3, 0.4])]
tangents = [np.array([1.0, 0.0]), np.array([0.0, 1.0])]
jvp_results = batch_jvp(tapes, tangents, reduction='append')
print(jvp_results)

