import pennylane as qml
import numpy as np

dev = qml.device("default.qubit", wires=1, shots=1)

@qml.qnode(dev)
def is_bomb(angle):
    qml.RY(angle, wires=0)
    return qml.sample(qml.PauliZ(0))

@qml.qnode(dev)
def bomb_tester(angle):
    qml.Hadamard(wires=0)
    qml.RY(angle, wires=0)
    qml.Hadamard(wires=0)
    return qml.sample(qml.PauliZ(0))

def simulate(angle, trials=10000):
    bomb_detected = 0
    bomb_exploded = 0
    for _ in range(trials):
        if is_bomb(angle) == 1:
            if bomb_tester(angle) == -1:
                bomb_detected += 1
            else:
                bomb_exploded += 1
    success_rate = bomb_detected / (bomb_detected + bomb_exploded) if (bomb_detected + bomb_exploded) > 0 else 0
    return success_rate

angle = np.pi / 4  # Example angle
success_rate = simulate(angle)
print(f"Success rate of detecting bombs without explosion: {success_rate:.4f}")

