import pytest
import pennylane as qml
from pennylane.optimize import GradientDescentOptimizer, AdamOptimizer, NesterovMomentumOptimizer
import numpy as np

# Define some simple cost functions
def univariate_cost(x):
    return (x - 2) ** 2

def multivariate_cost(x):
    return np.sum((x - np.array([1, 2, 3])) ** 2)

# Define a helper function to run optimization
def run_optimization(optimizer, cost_fn, init_params, steps=100, tol=1e-6):
    params = init_params
    for _ in range(steps):
        params, cost = optimizer.step_and_cost(cost_fn, params)
        if cost < tol:
            break
    return params, cost

# Test suite
@pytest.mark.parametrize("optimizer_class", [
    GradientDescentOptimizer,
    AdamOptimizer,
    NesterovMomentumOptimizer
])
@pytest.mark.parametrize("cost_fn, init_params", [
    (univariate_cost, np.array([0.0])),
    (multivariate_cost, np.array([0.0, 0.0, 0.0])),
    (multivariate_cost, [np.array([0.0]), np.array([0.0]), np.array([0.0])]),
    (multivariate_cost, [np.array([0.0, 0.0]), np.array([0.0])])
])
def test_optimizers(optimizer_class, cost_fn, init_params):
    optimizer = optimizer_class(stepsize=0.1)
    final_params, final_cost = run_optimization(optimizer, cost_fn, init_params)

    # Check if the final cost is below a threshold
    assert final_cost < 1e-3

    # Check if the final parameters are close to the expected minimum
    if cost_fn == univariate_cost:
        assert np.allclose(final_params, np.array([2.0]), atol=1e-1)
    elif cost_fn == multivariate_cost:
        assert np.allclose(final_params, np.array([1.0, 2.0, 3.0]), atol=1e-1)

# Run the tests
if __name__ == "__main__":
    pytest.main()

