import pytest
import pennylane as qml
from pennylane import numpy as np
import jax
import jax.numpy as jnp

def test_simple_while_loop():
    def cond_fn(x):
        return x < 5

    def body_fn(x):
        return x + 1

    @qml.qnode(qml.device('default.qubit', wires=1), interface='jax')
    def circuit():
        return qml.while_loop(cond_fn, body_fn, 0)

    result = circuit()
    assert result == 5

def test_while_loop_with_dynamic_arrays():
    def cond_fn(arr):
        return arr[-1] < 5

    def body_fn(arr):
        return jnp.append(arr, arr[-1] + 1)

    @qml.qnode(qml.device('default.qubit', wires=1), interface='jax')
    def circuit():
        return qml.while_loop(cond_fn, body_fn, jnp.array([0]))

    result = circuit()
    assert jnp.array_equal(result, jnp.array([0, 1, 2, 3, 4, 5]))

def test_nested_while_loops():
    def outer_cond(x):
        return x < 3

    def inner_cond(y):
        return y < 2

    def inner_body(y):
        return y + 1

    def outer_body(x):
        return qml.while_loop(inner_cond, inner_body, 0) + x

    @qml.qnode(qml.device('default.qubit', wires=1), interface='jax')
    def circuit():
        return qml.while_loop(outer_cond, outer_body, 0)

    result = circuit()
    assert result == 6

def test_while_loop_with_quantum_circuit():
    def cond_fn(x):
        return x < 2

    def body_fn(x):
        qml.RX(0.1, wires=0)
        return x + 1

    @qml.qnode(qml.device('default.qubit', wires=1), interface='jax')
    def circuit():
        qml.while_loop(cond_fn, body_fn, 0)
        return qml.expval(qml.PauliZ(0))

    result = circuit()
    assert np.isclose(result, np.cos(0.2))

def test_while_loop_gradient():
    def cond_fn(x):
        return x < 2

    def body_fn(x):
        qml.RX(0.1, wires=0)
        return x + 1

    @qml.qnode(qml.device('default.qubit', wires=1), interface='jax')
    def circuit(param):
        qml.RY(param, wires=0)
        qml.while_loop(cond_fn, body_fn, 0)
        return qml.expval(qml.PauliZ(0))

    param = jnp.array(0.1)
    grad_fn = jax.grad(circuit)
    grad = grad_fn(param)
    assert grad is not None

