import pennylane as qml
import numpy as np
import pytest

# Define a device
dev = qml.device("default.qubit", wires=2)

# Function to prepare a Bell state
@qml.qnode(dev)
def prepare_bell_state():
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])
    return qml.state()

# Function to perform classical shadow measurements
@qml.qnode(dev)
def classical_shadow_measurement():
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])
    qml.Hadamard(wires=0)
    return qml.sample(qml.PauliZ(0)), qml.sample(qml.PauliZ(1))

# Unit tests using pytest
def test_prepare_bell_state():
    state = prepare_bell_state()
    expected_state = np.array([1/np.sqrt(2), 0, 0, 1/np.sqrt(2)])
    assert np.allclose(state, expected_state), "Bell state preparation failed."

def test_classical_shadow_measurement():
    samples = classical_shadow_measurement()
    assert len(samples) == 2, "Measurement did not return expected number of samples."
    assert all(sample in [-1, 1] for sample in samples), "Measurement results are not valid PauliZ outcomes."

