if __name__ == "__main__":
    pytest.main([__file__])

import pytest
import pennylane as qml
from pennylane.transforms import commutation_dag
import numpy as np

# Define a simple quantum circuit
def circuit1(params):
    qml.RX(params[0], wires=0)
    qml.RY(params[1], wires=1)
    qml.CNOT(wires=[0, 1])
    return qml.expval(qml.PauliZ(0))

# Define another quantum circuit
def circuit2(params):
    qml.Hadamard(wires=0)
    qml.CZ(wires=[0, 1])
    qml.RZ(params[0], wires=1)
    return qml.expval(qml.PauliZ(1))

# Define a QNode for each circuit
dev = qml.device("default.qubit", wires=2)

@qml.qnode(dev)
def qnode1(params):
    circuit1(params)
    return qml.state()

@qml.qnode(dev)
def qnode2(params):
    circuit2(params)
    return qml.state()

# Test suite
@pytest.mark.parametrize("circuit, params", [
    (qnode1, [0.1, 0.2]),
    (qnode2, [0.3]),
])
def test_commutation_dag(circuit, params):
    dag = commutation_dag(circuit.qtape)
    assert dag is not None
    assert isinstance(dag, dict)
    assert len(dag) > 0

# Test for different automatic differentiation frameworks
@pytest.mark.parametrize("diff_method", ["backprop", "finite-diff", "parameter-shift"])
def test_commutation_dag_diff_methods(diff_method):
    dev = qml.device("default.qubit", wires=2)

    @qml.qnode(dev, diff_method=diff_method)
    def qnode(params):
        qml.RX(params[0], wires=0)
        qml.RY(params[1], wires=1)
        qml.CNOT(wires=[0, 1])
        return qml.expval(qml.PauliZ(0))

    params = np.array([0.1, 0.2], requires_grad=True)
    dag = commutation_dag(qnode.qtape)
    assert dag is not None
    assert isinstance(dag, dict)
    assert len(dag) > 0

import pennylane as qml
from pennylane.transforms import expand_fn_transform, get_transform_program
import pytest

def dummy_transform(tape):
    # A simple user-defined transformation that adds an identity operation
    with qml.tape.QuantumTape() as new_tape:
        for op in tape.operations:
            qml.apply(op)
        qml.Identity(wires=0)
    return new_tape

def test_expand_fn_transform_basic():
    dev = qml.device("default.qubit", wires=1)

    @qml.qnode(dev)
    def circuit():
        qml.Hadamard(wires=0)
        return qml.expval(qml.PauliZ(0))

    transformed_circuit = expand_fn_transform(dummy_transform)(circuit)
    result = transformed_circuit()
    assert len(transformed_circuit.qtape.operations) == 2
    assert transformed_circuit.qtape.operations[-1].name == "Identity"

def test_get_transform_program_basic():
    dev = qml.device("default.qubit", wires=1)

    @qml.qnode(dev)
    def circuit():
        qml.Hadamard(wires=0)
        return qml.expval(qml.PauliZ(0))

    program = get_transform_program(circuit)
    assert program is not None
    assert len(program) > 0

def test_expand_fn_transform_device_specific():
    dev = qml.device("default.qubit", wires=1)

    @qml.qnode(dev)
    def circuit():
        qml.RX(0.5, wires=0)
        return qml.expval(qml.PauliZ(0))

    transformed_circuit = expand_fn_transform(dummy_transform)(circuit)
    result = transformed_circuit()
    assert len(transformed_circuit.qtape.operations) == 2
    assert transformed_circuit.qtape.operations[-1].name == "Identity"

def test_get_transform_program_with_gradient_preprocessing():
    dev = qml.device("default.qubit", wires=1)

    @qml.qnode(dev, interface="autograd")
    def circuit(x):
        qml.RX(x, wires=0)
        return qml.expval(qml.PauliZ(0))

    program = get_transform_program(circuit)
    assert program is not None
    assert len(program) > 0

