import pytest
import pennylane as qml
from pennylane import numpy as np

def circuit1(params):
    qml.RX(params[0], wires=0)
    qml.RY(params[1], wires=1)
    return qml.state()

def circuit2(params):
    qml.RY(params[0], wires=0)
    qml.RX(params[1], wires=1)
    return qml.state()

@pytest.mark.parametrize("device", ["default.qubit", "lightning.qubit"])
@pytest.mark.parametrize("interface", ["autograd", "torch", "jax", "tf"])
def test_fidelity_and_gradient(device, interface):
    dev = qml.device(device, wires=2)

    @qml.qnode(dev, interface=interface)
    def qnode1(params):
        return circuit1(params)

    @qml.qnode(dev, interface=interface)
    def qnode2(params):
        return circuit2(params)

    params = np.array([0.1, 0.2], requires_grad=True)
    state1 = qnode1(params)
    state2 = qnode2(params)

    fidelity = qml.math.fidelity(state1, state2)

    grad_fn = qml.grad(lambda p: qml.math.fidelity(qnode1(p), qnode2(p)))
    grad = grad_fn(params)

    assert fidelity >= 0
    assert fidelity <= 1
    assert grad is not None

@pytest.mark.parametrize("device", ["default.qubit", "lightning.qubit"])
def test_custom_wire_labels(device):
    dev = qml.device(device, wires=["a", "b"])

    @qml.qnode(dev)
    def qnode(params):
        qml.RX(params[0], wires="a")
        qml.RY(params[1], wires="b")
        return qml.state()

    params = np.array([0.1, 0.2], requires_grad=True)
    state = qnode(params)

    assert state is not None

@pytest.mark.parametrize("device", ["default.qubit", "lightning.qubit"])
def test_broadcasting(device):
    dev = qml.device(device, wires=2)

    @qml.qnode(dev)
    def qnode(params):
        qml.broadcast(qml.RX, wires=[0, 1], pattern="single", parameters=params)
        return qml.state()

    params = np.array([0.1, 0.2], requires_grad=True)
    state = qnode(params)

    assert state is not None

