import pennylane as qml
import numpy as np
import pytest

# Mock functions to represent the internal functions from PennyLane
def _make_probs(state):
    return np.abs(state) ** 2

def _compute_cfim(probs, jacobian):
    return np.outer(jacobian, jacobian) / probs

def classical_fisher(probs, jacobian):
    return _compute_cfim(probs, jacobian)

def quantum_fisher(state, hessian):
    return np.real(np.dot(state.conj().T, np.dot(hessian, state)))

# Test fixtures
@pytest.fixture
def sample_state():
    return np.array([1/np.sqrt(2), 1/np.sqrt(2)])

@pytest.fixture
def sample_probs(sample_state):
    return _make_probs(sample_state)

@pytest.fixture
def sample_jacobian():
    return np.array([0.5, -0.5])

@pytest.fixture
def sample_hessian():
    return np.array([[1, 0], [0, 1]])

# Unit tests
def test_make_probs(sample_state):
    probs = _make_probs(sample_state)
    assert np.allclose(probs, [0.5, 0.5])

def test_compute_cfim(sample_probs, sample_jacobian):
    cfim = _compute_cfim(sample_probs, sample_jacobian)
    expected = np.outer(sample_jacobian, sample_jacobian) / sample_probs
    assert np.allclose(cfim, expected)

def test_classical_fisher(sample_probs, sample_jacobian):
    cf = classical_fisher(sample_probs, sample_jacobian)
    expected = _compute_cfim(sample_probs, sample_jacobian)
    assert np.allclose(cf, expected)

def test_quantum_fisher(sample_state, sample_hessian):
    qf = quantum_fisher(sample_state, sample_hessian)
    expected = np.real(np.dot(sample_state.conj().T, np.dot(sample_hessian, sample_state)))
    assert np.allclose(qf, expected)

# Integration test with a QNode
@pytest.mark.parametrize("dev_name", ["default.qubit", "lightning.qubit"])
def test_integration(dev_name):
    dev = qml.device(dev_name, wires=1)

    @qml.qnode(dev)
    def circuit():
        qml.Hadamard(wires=0)
        return qml.state()

    state = circuit()
    probs = _make_probs(state)
    jacobian = np.array([0.5, -0.5])  # Mock jacobian
    hessian = np.array([[1, 0], [0, 1]])  # Mock hessian

    cf = classical_fisher(probs, jacobian)
    qf = quantum_fisher(state, hessian)

    assert np.allclose(cf, _compute_cfim(probs, jacobian))
    assert np.allclose(qf, np.real(np.dot(state.conj().T, np.dot(hessian, state))))

