    state = circuit()
    expected_state = np.array([1/np.sqrt(2), 0, 0, 1/np.sqrt(2)])
    assert np.allclose(state, expected_state), "Snapshot operation failed."

@pytest.mark.parametrize("operation", [qml.Barrier, qml.WireCut, qml.Snapshot])
