import pennylane as qml
from pennylane import numpy as np
import pytest

# Define a simple quantum circuit
def circuit_single_param(params):
    qml.RX(params[0], wires=0)
    return qml.expval(qml.PauliZ(0))

def circuit_multi_param(params):
    qml.RX(params[0], wires=0)
    qml.RY(params[1], wires=0)
    return qml.expval(qml.PauliZ(0))

# Define cost functions
def cost_single_param(params):
    return circuit_single_param(params)

def cost_multi_param(params):
    return circuit_multi_param(params)

# Test suite for MomentumQNGOptimizer
@pytest.mark.parametrize("momentum", [0.1, 0.5, 0.9])
@pytest.mark.parametrize("cost_fn, init_params", [
    (cost_single_param, np.array([0.1])),
    (cost_multi_param, np.array([0.1, 0.2]))
])
def test_momentum_qng_optimizer(momentum, cost_fn, init_params):
    opt = qml.MomentumQNGOptimizer(stepsize=0.1, momentum=momentum)
    params = init_params
    prev_cost = cost_fn(params)

    for _ in range(10):
        params, cost = opt.step_and_cost(cost_fn, params)
        assert cost <= prev_cost, "Cost did not decrease"
        prev_cost = cost

# Test explicit gradient function
def test_explicit_gradient():
    opt = qml.MomentumQNGOptimizer(stepsize=0.1, momentum=0.5)
    init_params = np.array([0.1, 0.2])

    def grad_fn(params):
        return np.array([0.1, 0.1])

    params = init_params
    prev_cost = cost_multi_param(params)

    for _ in range(10):
        params, cost = opt.step_and_cost(cost_multi_param, params, grad_fn=grad_fn)
        assert cost <= prev_cost, "Cost did not decrease"
        prev_cost = cost

# Run the tests
if __name__ == "__main__":
    pytest.main()

