import pennylane as qml
from pennylane import numpy as np
import pytest

# Define a simple quantum circuit
def simple_circuit():
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])

# Define a QNode
@qml.qnode(qml.device('default.qubit', wires=2))
def circuit_with_purity():
    simple_circuit()
    return qml.expval(qml.PurityMP(wires=[0, 1]))

# Test the purity measurement
def test_purity_measurement():
    purity = circuit_with_purity()
    assert np.isclose(purity, 1.0), f"Expected purity to be 1.0, got {purity}"

# Test the gradient of the purity measurement
def test_purity_gradient():
    dev = qml.device('default.qubit', wires=2)

    @qml.qnode(dev)
    def circuit_with_param(theta):
        qml.RY(theta, wires=0)
        qml.CNOT(wires=[0, 1])
        return qml.expval(qml.PurityMP(wires=[0, 1]))

    theta = np.pi / 4
    grad_fn = qml.grad(circuit_with_param)
    grad = grad_fn(theta)
    assert grad is not None, "Gradient should not be None"

# Test with noisy channel
def test_noisy_channel():
    dev = qml.device('default.mixed', wires=2)

    @qml.qnode(dev)
    def noisy_circuit():
        simple_circuit()
        qml.DepolarizingChannel(0.1, wires=0)
        return qml.expval(qml.PurityMP(wires=[0, 1]))

    purity = noisy_circuit()
    assert 0 <= purity <= 1, f"Purity should be between 0 and 1, got {purity}"

# Run the tests
test_purity_measurement()
test_purity_gradient()
test_noisy_channel()

import pennylane as qml
from pennylane import numpy as np
import unittest
from qiskit import QuantumCircuit
from qiskit.qasm import pi

class TestToOpenQASM(unittest.TestCase):

    def test_native_qasm_gates(self):
        dev = qml.device("default.qubit", wires=2)

        @qml.qnode(dev)
        def circuit():
            qml.Hadamard(wires=0)
            qml.CNOT(wires=[0, 1])
            return qml.state()

        qasm_str = circuit.to_openqasm()
        self.assertIn("h q[0];", qasm_str)
        self.assertIn("cx q[0], q[1];", qasm_str)

    def test_decompositions(self):
        dev = qml.device("default.qubit", wires=2)

        @qml.qnode(dev)
        def circuit():
            qml.RX(np.pi/2, wires=0)
            return qml.state()

        qasm_str = circuit.to_openqasm()
        self.assertIn("u3", qasm_str)

    def test_unused_wires(self):
        dev = qml.device("default.qubit", wires=3)

        @qml.qnode(dev)
        def circuit():
            qml.Hadamard(wires=0)
            return qml.state()

        qasm_str = circuit.to_openqasm()
        self.assertNotIn("q[2]", qasm_str)

    def test_unsupported_operations(self):
        dev = qml.device("default.qubit", wires=2)

        @qml.qnode(dev)
        def circuit():
            qml.T(wires=0)
            return qml.state()

        with self.assertRaises(ValueError):
            circuit.to_openqasm()

    def test_integration_with_qiskit(self):
        dev = qml.device("default.qubit", wires=2)

        @qml.qnode(dev)
        def circuit():
            qml.Hadamard(wires=0)
            qml.CNOT(wires=[0, 1])
            return qml.state()

        qasm_str = circuit.to_openqasm()
        qiskit_circuit = QuantumCircuit.from_qasm_str(qasm_str)
        self.assertEqual(qiskit_circuit.count_ops().get('h', 0), 1)
        self.assertEqual(qiskit_circuit.count_ops().get('cx', 0), 1)

if __name__ == "__main__":
    unittest.main()

