import pennylane as qml
import numpy as np
import pytest

# Define a device
dev = qml.device("default.qubit", wires=2)

# Define a QNode to prepare a Bell state
@qml.qnode(dev)
def prepare_bell_state():
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])
    return qml.state()

# Define a QNode to prepare a superposition state
@qml.qnode(dev)
def prepare_superposition_state():
    qml.Hadamard(wires=0)
    qml.Hadamard(wires=1)
    return qml.state()

# Define a QNode to prepare a product state
@qml.qnode(dev)
def prepare_product_state():
    qml.PauliX(wires=0)
    qml.PauliY(wires=1)
    return qml.state()

# Define a function to compute classical shadows
def classical_shadows(circuit):
    return qml.shadows.classical_shadow(circuit, wires=[0, 1])

# Test cases to verify the functionality
def test_bell_state():
    state = prepare_bell_state()
    shadow = classical_shadows(prepare_bell_state)
    assert np.allclose(state, [1/np.sqrt(2), 0, 0, 1/np.sqrt(2)])
    assert shadow.shape == (1, 2)

def test_superposition_state():
    state = prepare_superposition_state()
    shadow = classical_shadows(prepare_superposition_state)
    assert np.allclose(state, [0.5, 0.5, 0.5, 0.5])
    assert shadow.shape == (1, 2)

def test_product_state():
    state = prepare_product_state()
    shadow = classical_shadows(prepare_product_state)
    assert np.allclose(state, [0, 0, 0, 1j])
    assert shadow.shape == (1, 2)

