import pytest
import pennylane as qml
from pennylane import numpy as np

def trace_distance(rho, sigma):
    """Calculate the trace distance between two density matrices."""
    diff = rho - sigma
    eigvals = np.linalg.eigvalsh(diff)
    return 0.5 * np.sum(np.abs(eigvals))

@pytest.fixture
def qnodes():
    dev = qml.device("default.qubit", wires=1)

    @qml.qnode(dev)
    def circuit1():
        qml.Hadamard(wires=0)
        return qml.state()

    @qml.qnode(dev)
    def circuit2():
        qml.PauliX(wires=0)
        return qml.state()

    return circuit1, circuit2

def test_trace_distance(qnodes):
    circuit1, circuit2 = qnodes
    rho = np.outer(circuit1(), circuit1().conj())
    sigma = np.outer(circuit2(), circuit2().conj())
    td = trace_distance(rho, sigma)
    assert np.isclose(td, 1.0)

@pytest.mark.parametrize("device", ["default.qubit", "lightning.qubit"])
