import pennylane as qml
from pennylane import numpy as np

# Basic mid-circuit measurement
dev = qml.device("default.qubit", wires=2)

@qml.qnode(dev)
def basic_measurement():
    qml.Hadamard(wires=0)
    m = qml.measure(0)
    qml.cond(m, qml.PauliX)(wires=1)
    return qml.probs(wires=[0, 1])

print("Basic Measurement:", basic_measurement())

# Postselection example
@qml.qnode(dev)
def postselection():
    qml.Hadamard(wires=0)
    m = qml.measure(0)
    qml.cond(m == 1, qml.PauliX)(wires=1)
    return qml.probs(wires=[0, 1])

print("Postselection:", postselection())

# Qubit reset example
@qml.qnode(dev)
def qubit_reset():
    qml.Hadamard(wires=0)
    m = qml.measure(0)
    qml.reset(wires=0)
    qml.cond(m, qml.PauliX)(wires=1)
    return qml.probs(wires=[0, 1])

print("Qubit Reset:", qubit_reset())

# Dynamic circuit with conditional operations
@qml.qnode(dev)
def dynamic_circuit():
    qml.Hadamard(wires=0)
    m = qml.measure(0)
    qml.cond(m, qml.PauliX)(wires=1)
    qml.cond(m == 0, qml.PauliZ)(wires=1)
    return qml.probs(wires=[0, 1])

print("Dynamic Circuit:", dynamic_circuit())

