import pytest
import pennylane as qml
from pennylane import numpy as np

def von_neumann_entropy(rho):
    """Calculate the Von Neumann entropy of a density matrix."""
    eigvals = np.linalg.eigvalsh(rho)
    eigvals = eigvals[eigvals > 0]  # Filter out zero eigenvalues
    return -np.sum(eigvals * np.log(eigvals))

def mutual_information(rho, subsystems):
    """Calculate the mutual information between two subsystems."""
    rho_A = qml.math.reduce_dm(rho, subsystems[0])
    rho_B = qml.math.reduce_dm(rho, subsystems[1])
    S_A = von_neumann_entropy(rho_A)
    S_B = von_neumann_entropy(rho_B)
    S_AB = von_neumann_entropy(rho)
    return S_A + S_B - S_AB

@pytest.mark.parametrize("interface", ["autograd", "jax", "tf", "torch"])
@pytest.mark.parametrize("diff_method", ["backprop", "finite-diff", "parameter-shift"])
def test_von_neumann_entropy(interface, diff_method):
    dev = qml.device("default.qubit", wires=2)

    @qml.qnode(dev, interface=interface, diff_method=diff_method)
    def circuit():
        qml.Hadamard(wires=0)
        qml.CNOT(wires=[0, 1])
        return qml.density_matrix(wires=[0, 1])

    rho = circuit()
    entropy = von_neumann_entropy(rho)
    expected_entropy = 1.0  # Analytical result for a maximally entangled state
    assert np.isclose(entropy, expected_entropy, atol=1e-5)

@pytest.mark.parametrize("interface", ["autograd", "jax", "tf", "torch"])
@pytest.mark.parametrize("diff_method", ["backprop", "finite-diff", "parameter-shift"])
def test_mutual_information(interface, diff_method):
    dev = qml.device("default.qubit", wires=2)

    @qml.qnode(dev, interface=interface, diff_method=diff_method)
    def circuit():
        qml.Hadamard(wires=0)
        qml.CNOT(wires=[0, 1])
        return qml.density_matrix(wires=[0, 1])

    rho = circuit()
    mi = mutual_information(rho, [[0], [1]])
    expected_mi = 2.0  # Analytical result for a maximally entangled state
    assert np.isclose(mi, expected_mi, atol=1e-5)

