import pennylane as qml
from pennylane import numpy as np
import pytest

# Custom expansion function
def custom_expansion(tape):
    new_tape = qml.tape.QuantumTape()
    for op in tape.operations:
        if isinstance(op, qml.RX):
            new_tape += qml.Rot(op.parameters[0], 0, 0, wires=op.wires)
        else:
            new_tape += op
    return new_tape

# Define a QNode with custom expansion
dev = qml.device("default.qubit", wires=1)

@qml.qnode(dev, expansion_strategy=custom_expansion)
def circuit_with_custom_expansion(angle):
    qml.RX(angle, wires=0)
    return qml.expval(qml.PauliZ(0))

# Unit tests
def test_custom_expansion():
    angle = np.pi / 4
    result = circuit_with_custom_expansion(angle)
    expected = np.cos(angle)
    assert np.isclose(result, expected), f"Expected {expected}, got {result}"

def test_custom_expansion_decomposition():
    tape = qml.tape.QuantumTape()
    with tape:
        qml.RX(np.pi / 4, wires=0)
    expanded_tape = custom_expansion(tape)
    assert len(expanded_tape.operations) == 1
    assert isinstance(expanded_tape.operations[0], qml.Rot)

