# Test fidelity between circuits
def test_fidelity():
    params = np.array([0.1, 0.2], requires_grad=True)
    result_default = circuit_default(params)
    result_lightning = circuit_lightning(params)
    assert np.isclose(result_default, result_lightning, atol=1e-5)

# Test gradients
def test_gradients():
