import pytest
import numpy as np
import pennylane as qml
from pennylane.qinfo import classical_fisher, quantum_fisher

def _make_probs(state):
    return np.abs(state) ** 2

def _compute_cfim(probs, jacobian):
    return np.einsum('ij,ik->jk', jacobian / probs, jacobian)

@pytest.mark.parametrize("interface", ["autograd", "jax", "torch", "tf"])
def test_classical_fisher(interface):
    dev = qml.device("default.qubit", wires=1)

    @qml.qnode(dev, interface=interface)
    def circuit(theta):
        qml.RX(theta, wires=0)
        return qml.state()

    theta = 0.5
    state = circuit(theta)
    probs = _make_probs(state)
    jacobian = qml.jacobian(circuit)(theta)
    cfim = _compute_cfim(probs, jacobian)

    cfim_pl = classical_fisher(circuit, [theta])
    assert np.allclose(cfim, cfim_pl, atol=1e-5)

@pytest.mark.parametrize("interface", ["autograd", "jax", "torch", "tf"])
def test_quantum_fisher(interface):
    dev = qml.device("default.qubit", wires=1)

    @qml.qnode(dev, interface=interface)
    def circuit(theta):
        qml.RX(theta, wires=0)
        return qml.state()

    theta = 0.5
    qfim_pl = quantum_fisher(circuit, [theta])

    # Quantum Fisher Information for a single RX gate
    qfim_expected = np.array([[1.0]])

    assert np.allclose(qfim_pl, qfim_expected, atol=1e-5)

