import pytest
import pennylane as qml
from pennylane import numpy as np

def iterative_qpe(U, num_qubits, num_iterations):
    dev = qml.device("default.qubit", wires=num_qubits + 1)

    @qml.qnode(dev)
    def circuit():
        qml.Hadamard(wires=0)
        for _ in range(num_iterations):
            qml.ControlledQubitUnitary(U, control_wires=0, wires=range(1, num_qubits + 1))
            qml.Hadamard(wires=0)
        return qml.probs(wires=0)

    return circuit()

def standard_qpe(U, num_qubits):
    dev = qml.device("default.qubit", wires=num_qubits + 1)

    @qml.qnode(dev)
    def circuit():
        for i in range(num_qubits):
            qml.Hadamard(wires=i)
        for i in range(num_qubits):
            qml.ControlledQubitUnitary(U, control_wires=i, wires=num_qubits)
        qml.QFT(wires=range(num_qubits), inverse=True)
        return qml.probs(wires=range(num_qubits))

    return circuit()

@pytest.mark.parametrize("backend", ["default.qubit", "lightning.qubit"])
def test_iterative_qpe_correctness(backend):
    num_qubits = 2
    num_iterations = 3
    U = np.array([[1, 0], [0, np.exp(2j * np.pi / 4)]])

    iterative_result = iterative_qpe(U, num_qubits, num_iterations)
    standard_result = standard_qpe(U, num_qubits)

    assert np.allclose(iterative_result, standard_result, atol=1e-2)

@pytest.mark.parametrize("backend", ["default.qubit.jax", "default.qubit.torch", "default.qubit.tf"])
def test_iterative_qpe_gradients(backend):
    num_qubits = 2
    num_iterations = 3
    U = np.array([[1, 0], [0, np.exp(2j * np.pi / 4)]])

    dev = qml.device(backend, wires=num_qubits + 1)

    @qml.qnode(dev, interface=backend.split('.')[-1])
    def circuit():
        qml.Hadamard(wires=0)
        for _ in range(num_iterations):
            qml.ControlledQubitUnitary(U, control_wires=0, wires=range(1, num_qubits + 1))
            qml.Hadamard(wires=0)
        return qml.expval(qml.PauliZ(0))

    grad_fn = qml.grad(circuit)
    grad = grad_fn()

    assert grad is not None

