        @qml.qnode(dev)
        def circuit():
            qml.WireCut(wires=[])
            return qml.state()

        circuit()

    with pytest.raises(ValueError, match="Wires must be specified"):
        @qml.qnode(dev)
        def circuit():
            qml.Snapshot(wires=[])
            return qml.state()

        circuit()

