import pennylane as qml
from pennylane import numpy as np
import unittest
from qiskit import QuantumCircuit
from qiskit.qasm import pi

class TestToOpenQASM(unittest.TestCase):

    def setUp(self):
        self.dev = qml.device("default.qubit", wires=2)

    def test_native_qasm_gates(self):
        @qml.qnode(self.dev)
        def circuit():
            qml.Hadamard(wires=0)
            qml.CNOT(wires=[0, 1])
            return qml.state()

        qasm_output = circuit.qtape.to_openqasm()
        expected_qasm = """OPENQASM 2.0;
include "qelib1.inc";
qreg q[2];
h q[0];
cx q[0],q[1];
"""
        self.assertEqual(qasm_output.strip(), expected_qasm.strip())

    def test_decomposition_of_unsupported_gates(self):
        @qml.qnode(self.dev)
        def circuit():
            qml.Toffoli(wires=[0, 1, 2])
            return qml.state()

        qasm_output = circuit.qtape.to_openqasm()
        self.assertIn("ccx", qasm_output)

    def test_validation_against_qiskit(self):
        @qml.qnode(self.dev)
        def circuit():
            qml.RX(np.pi / 2, wires=0)
            qml.CRY(np.pi / 4, wires=[0, 1])
            return qml.state()

        qasm_output = circuit.qtape.to_openqasm()

        # Create equivalent Qiskit circuit
        qc = QuantumCircuit(2)
        qc.rx(pi / 2, 0)
        qc.cry(pi / 4, 0, 1)
        qiskit_qasm = qc.qasm()

        self.assertEqual(qasm_output.strip(), qiskit_qasm.strip())

if __name__ == "__main__":
    unittest.main()

