import pytest
import pennylane as qml
from pennylane import numpy as np

# Define a simple quantum circuit
def circuit(params):
    qml.RX(params[0], wires=0)
    qml.RY(params[1], wires=0)
    return qml.state()

# Define a target state
target_state = np.array([0.70710678, 0.70710678])

# Define the QNode
dev = qml.device("default.qubit", wires=1)

@qml.qnode(dev)
def quantum_circuit(params):
    circuit(params)
    return qml.state()

# Define the trace distance
def trace_distance(state, target):
    return 0.5 * np.linalg.norm(state - target)

# Define the gradient of the trace distance
def trace_distance_gradient(params):
    state = quantum_circuit(params)
    grad_fn = qml.grad(lambda p: trace_distance(quantum_circuit(p), target_state))
    return grad_fn(params)

# Parameterized test cases
@pytest.mark.parametrize("params", [
    (np.array([0.0, 0.0]),),
    (np.array([np.pi/4, np.pi/4]),),
    (np.array([np.pi/2, np.pi/2]),),
])
def test_trace_distance(params):
    state = quantum_circuit(params)
    distance = trace_distance(state, target_state)
    assert distance >= 0

@pytest.mark.parametrize("params", [
    (np.array([0.0, 0.0]),),
    (np.array([np.pi/4, np.pi/4]),),
    (np.array([np.pi/2, np.pi/2]),),
])
def test_trace_distance_gradient(params):
    grad = trace_distance_gradient(params)
    assert grad is not None

